package com.metrom.app.engine

import android.content.Context
import java.io.ByteArrayOutputStream
import java.util.Base64
import java.util.concurrent.atomic.AtomicReference
import java.util.zip.Inflater

/**
 * Chug one-shots: prefers real WAV samples, falls back to embedded PCM.
 *
 * Load order (see [WavSampleLoader]):
 * 1. filesDir/chug/chug.wav (+ optional chug_accent.wav) — drop-in, no rebuild
 * 2. assets/chug/ WAV files — ship with the APK
 * 3. res/raw/chug — alternate APK path
 * 4. Embedded synthetic fallback
 */
internal object ChugSamples {
    private val normalRef = AtomicReference<ShortArray?>(null)
    private val accentRef = AtomicReference<ShortArray?>(null)

    fun prepare(context: Context) {
        if (normalRef.get() != null && accentRef.get() != null) return
        val app = context.applicationContext
        // Tiny WAVs — load on the main thread at startup so Chug never
        // caches the embedded fallback before a real sample is ready.
        normalRef.compareAndSet(null, load(app, accent = false))
        accentRef.compareAndSet(null, load(app, accent = true))
    }

    val normal: ShortArray
        get() = normalRef.get() ?: decode(NORMAL_B64).also { normalRef.compareAndSet(null, it) }

    val accent: ShortArray
        get() = accentRef.get() ?: decode(ACCENT_B64).also { accentRef.compareAndSet(null, it) }

    private fun load(context: Context, accent: Boolean): ShortArray =
        WavSampleLoader.loadChug(context, accent)
            ?: decode(if (accent) ACCENT_B64 else NORMAL_B64)

    private const val NORMAL_B64 = ""
    private const val ACCENT_B64 = ""

    private fun decode(b64: String): ShortArray {
        val inflated = inflate(Base64.getDecoder().decode(b64))
        val count = inflated.size / 2
        val out = ShortArray(count)
        var i = 0
        var s = 0
        while (s < count) {
            val lo = inflated[i].toInt() and 0xff
            val hi = inflated[i + 1].toInt() and 0xff
            out[s++] = ((hi shl 8) or lo).toShort()
            i += 2
        }
        return out
    }

    private fun inflate(data: ByteArray): ByteArray {
        val inflater = Inflater()
        inflater.setInput(data)
        val buf = ByteArray(8192)
        val out = ByteArrayOutputStream(data.size * 3)
        while (!inflater.finished()) {
            val n = inflater.inflate(buf)
            if (n <= 0 && inflater.needsInput()) break
            if (n > 0) out.write(buf, 0, n)
        }
        inflater.end()
        return out.toByteArray()
    }
}
